#!/usr/bin/env node
/**
 * PQP — generate a chapter's browser bundle from its editorial data module.
 *
 *   node scripts/pqp/build-web-bundle.mjs --chapter=C02
 *
 * The bundle is the PUBLIC half of a route: the scene copy a reader sees and
 * the three recall labels they choose between. It is generated rather than
 * hand-written so it cannot drift from the manifests — both come from
 * `scripts/pqp/chapters/<code>.mjs`.
 *
 * What CANNOT reach here, structurally: the correct recall option. The chapter
 * module does not contain it (it lives only in the server-side exercise
 * catalog), so there is nothing for this script to leak.
 *
 * C01's bundle predates this generator and stays hand-written; regenerating it
 * is not worth touching a file whose DRAFTs are already in production.
 */
import { writeFileSync } from "node:fs";

const arg = process.argv.find((a) => a.startsWith("--chapter="));
const code = (arg ? arg.slice(10) : "").toUpperCase();
if (!code) throw new Error("MISSING_CHAPTER");
const { CHAPTER, MICROGUIDES } = await import(
  `./chapters/${code.toLowerCase()}.mjs`
);

const q = (s) => JSON.stringify(s);
const scene = (mg, kind) => mg.scenes.find((s) => s.kind === kind);
const chapterNumber = CHAPTER.keyPrefix.replace("pqp-c", "");

const entries = MICROGUIDES.map((mg) => {
  const intro = scene(mg, "INTRO");
  const passage = scene(mg, "PASSAGE");
  const concept = scene(mg, "CONCEPT");
  const practice = scene(mg, "PRACTICE");
  const summary = scene(mg, "SUMMARY");
  return `  {
    slug: ${q(mg.slug)},
    practiceSlug: ${q(mg.practiceSlug)},
    title: ${q(mg.title)},
    summary: ${q(intro.body[0])},
    duration: ${q(mg.duration)},
    intro: {
      title: ${q(intro.title)},
      body: [${intro.body.map(q).join(", ")}],
      note: ${q(intro.note)},
    },
    passage: {
      title: ${q(passage.title)},
      body: ${q(passage.body.join(" "))},
    },
    concept: {
      title: ${q(concept.title)},
      body: [${concept.body.map(q).join(", ")}],
      note: ${q(concept.note)},
    },
    practice: {
      title: ${q(practice.title)},
      body: [${practice.body.map(q).join(", ")}],
      note: ${q(practice.note)},
    },
    recall: {
      question: ${q(mg.recall.question)},
      options: [
${mg.recall.options.map((o) => `        { optionKey: ${q(o.optionKey)}, label: ${q(o.label)} },`).join("\n")}
      ],
    },
    summaryScene: {
      title: ${q(summary.title)},
      body: [${summary.body.map(q).join(", ")}],
    },
  },`;
}).join("\n");

const constName = `PQP_${CHAPTER.code}_MICROGUIDES`;
const file = `/**
 * PQP-${CHAPTER.code}'s ${MICROGUIDES.length} microguides, as the browser needs them.
 *
 * GENERATED by \`scripts/pqp/build-web-bundle.mjs --chapter=${CHAPTER.code}\` from
 * \`scripts/pqp/chapters/${CHAPTER.code.toLowerCase()}.mjs\`, which is also what the manifests are
 * built from. Editing this file by hand would let the bundle drift from the
 * manifests the DRAFTs were created from; edit the chapter module and
 * regenerate.
 *
 * This is the PUBLIC half. The three recall labels are here so a reader can
 * choose between them; which one is correct is not, and is not derivable from
 * anything in this file — it lives only in the server-side exercise catalog.
 *
 * The extra scenes each Experience has live in the stored definition and are
 * drawn by the player from there. A guide has three obligatory steps, and the
 * optional scenes are optional by design: listing them here would turn an
 * invitation into a requirement for finishing.
 */

import type { GuidePresentation } from "./guide-presentation";
import type { GuideReaderCopy } from "./guide-reader-copy";
import {
  microguidePresentation,
  microguideReaderCopy,
  type MicroguideChapter,
  type MicroguideEntry,
} from "./guide-microguide-bundle";

const PQP_${CHAPTER.code}: MicroguideChapter = {
  // The EDITORIAL chapter number, matching the guide keys. Its PLATFORM order
  // is ${CHAPTER.chapterOrder} — unit 1 is the front matter.
  keyPrefix: ${q(CHAPTER.keyPrefix)},
  chapterLabel: ${q(`capítulo ${chapterNumber}`)},
};

export const ${constName}: readonly MicroguideEntry[] = [
${entries}
];

export const PQP_${CHAPTER.code}_PRESENTATIONS: readonly GuidePresentation[] =
  ${constName}.map((m) => microguidePresentation(PQP_${CHAPTER.code}, m));

export const PQP_${CHAPTER.code}_READER_COPY: readonly GuideReaderCopy[] =
  ${constName}.map((m) => microguideReaderCopy(PQP_${CHAPTER.code}, m));
`;

const out = `apps/web/src/components/dashboard/guide/pqp-${CHAPTER.code.toLowerCase()}-microguides.ts`;
writeFileSync(out, file);
console.log(`wrote ${MICROGUIDES.length} entries to ${out}`);
